import{_ as r,o as a,c as s,ah as t}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Former vos équipes sur devis","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/entreprises/formation-sur-devis.md","filePath":"src/guide/entreprises/formation-sur-devis.md"}'),o={name:"guide/entreprises/formation-sur-devis.md"};function n(i,e,u,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="former-vos-equipes-sur-devis" tabindex="-1">Former vos équipes sur devis <a class="header-anchor" href="#former-vos-equipes-sur-devis" aria-label="Permalink to &quot;Former vos équipes sur devis&quot;">​</a></h1><p>Une entreprise peut commander une formation du catalogue pour ses salariés : c&#39;est la <strong>formation sur devis</strong>. Elle donne lieu à une ou plusieurs <strong>cohortes dédiées</strong>, réservées à l&#39;entreprise.</p><p>Il n&#39;y a pas de candidature, pas de convention individuelle et pas de facture par salarié : l&#39;entreprise reçoit <strong>un devis, puis une facture unique</strong>.</p><h2 id="deposer-une-demande" tabindex="-1">Déposer une demande <a class="header-anchor" href="#deposer-une-demande" aria-label="Permalink to &quot;Déposer une demande&quot;">​</a></h2><p>Un compte organisation n&#39;est pas obligatoire : la personne de contact, avec un compte individu, peut faire la demande. Elle se fait de deux façons :</p><ul><li>depuis le <strong>site NextBoxx</strong> ;</li><li>depuis Kura, <strong>Parcours → Mes demandes entreprise → Nouvelle demande</strong>, en choisissant le type « Formation de mes équipes ».</li></ul><p>Indiquez la raison sociale, le programme du catalogue, le format, le nombre de personnes, le démarrage souhaité (facultatif) et un message. La demande reçoit une référence <code>DEM-NB</code> et le Coordinateur pédagogique est prévenu.</p><h2 id="le-devis" tabindex="-1">Le devis <a class="header-anchor" href="#le-devis" aria-label="Permalink to &quot;Le devis&quot;">​</a></h2><p>Le Coordinateur étudie la demande et vous envoie un <strong>devis</strong> (<code>DEV-NB</code>) par e-mail, en PDF : programme, format, effectif, dates, rythme et montant total en FCFA. Au-delà de <strong>15 apprenants</strong>, le devis prévoit <strong>une cohorte par tranche de 15</strong>. Un seul devis attend une réponse à la fois.</p><p>Dans <strong>Mes demandes entreprise</strong>, la page de la demande indique où l&#39;on en est : « Reçue », « En cours », « Devis envoyé », « Acceptée » ou « Clôturée ».</p><h3 id="accepter-ou-refuser" tabindex="-1">Accepter ou refuser <a class="header-anchor" href="#accepter-ou-refuser" aria-label="Permalink to &quot;Accepter ou refuser&quot;">​</a></h3><p>Quand le devis est prêt, vous l&#39;acceptez ou le refusez depuis la demande, avant sa date de début. Le Coordinateur peut aussi enregistrer pour vous une acceptation reçue par un autre moyen.</p><ul><li><strong>Refus.</strong> Dites pourquoi si vous le souhaitez : la demande reste en cours, et le Coordinateur peut vous envoyer un devis révisé ou clore la demande.</li><li><strong>Acceptation.</strong> Elle ouvre en une fois vos cohortes dédiées et émet la <strong>facture unique</strong>, du montant du devis, à votre raison sociale, <strong>échue au premier jour de la formation</strong>.</li></ul><h2 id="ajouter-vos-apprenants" tabindex="-1">Ajouter vos apprenants <a class="header-anchor" href="#ajouter-vos-apprenants" aria-label="Permalink to &quot;Ajouter vos apprenants&quot;">​</a></h2><p>Une fois les cohortes ouvertes, ajoutez vos salariés (leur nom et leur adresse e-mail) depuis la demande, <strong>15 au plus par cohorte</strong>, tant que la cohorte n&#39;est pas terminée ni annulée.</p><p>Pour chaque salarié, Kura crée ou réutilise un compte, l&#39;inscrit <strong>directement et activement</strong>, lui donne le rôle Apprenant, lui envoie son livret d&#39;accueil et ouvre son accès à Sève. Il reçoit son accès par e-mail.</p><p>Le Coordinateur peut retirer un apprenant en enregistrant son abandon.</p><h2 id="le-paiement-et-ses-retards" tabindex="-1">Le paiement et ses retards <a class="header-anchor" href="#le-paiement-et-ses-retards" aria-label="Permalink to &quot;Le paiement et ses retards&quot;">​</a></h2><p>La facture suit la chronologie habituelle : rappels avant l&#39;échéance, rappel le lendemain, relance à J+7, retard et moratoire de 15 jours à J+15.</p><p>À <strong>J+30</strong> sans paiement, les inscriptions de vos cohortes dédiées et <strong>leur accès à Sève sont suspendus</strong>. Le contact est prévenu. Le paiement les rétablit. Un apprenant ajouté pendant l&#39;impayé commence suspendu. Les comptes de vos salariés restent actifs.</p><p>Pour un apprenant d&#39;une cohorte dédiée, la condition « solde payé » du certificat est remplie quand <strong>la facture de la demande est payée</strong>.</p>',21)])])}const v=r(o,[["render",n]]);export{m as __pageData,v as default};
